// Función auxiliar para gestionar los Tagged Values dinámicamente
function setTaggedValue(element /* : EA.Element */, tagName, tagValue) {
    var tags /* : EA.Collection */ = element.TaggedValues;
    var tag /* : EA.TaggedValue */ = null;

    // Buscar si el Tagged Value ya existe
    for (var i = 0; i < tags.Count; i++) {
        var currentTag = tags.GetAt(i);
        if (currentTag.Name === tagName) {
            tag = currentTag;
            break;
        }
    }

    // Si no existe, crearlo
    if (tag == null) {
        tag = tags.AddNew(tagName, "TaggedValue");
        tag.Update();
    }

    // Forzar que el valor sea texto y limpiar undefined/null
    tagValue = tagValue ? String(tagValue) : "";

    // Evaluar si necesita usar el campo <memo> por longitud o saltos de línea
    if (tagValue.length > 255 || tagValue.indexOf('\n') !== -1) {
        tag.Value = "<memo>";
        tag.Notes = tagValue;
    } else {
        tag.Value = tagValue;
        tag.Notes = ""; 
    }
    
    tag.Update();
}

